appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  function decodeB64(s) {
    if (!s) {
      return [];
    }
    try {
      return JSON.parse(decodeURIComponent(escape(atob(s))));
    } catch (e) {
      return [];
    }
  }
  var role = 'viewer';
  try {
    var model = appsmith.model || {};
    role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'dashboard';
    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';
    var MENU = [{
      section: 'Análisis',
      items: [{
        id: 'dashboard',
        label: 'Dashboard',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'mentions',
        label: 'Menciones',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'analytics',
        label: 'Analítica',
        roles: ['admin', 'analyst']
      }, {
        id: 'competitors',
        label: 'Competencia',
        roles: ['admin', 'analyst']
      }]
    }, {
      section: 'Gestión',
      items: [{
        id: 'targets',
        label: 'Objetivos',
        roles: ['admin', 'analyst']
      }, {
        id: 'alerts',
        label: 'Alertas',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'reports',
        label: 'Reportes',
        roles: ['admin', 'analyst', 'viewer']
      }]
    }, {
      section: 'Administración',
      items: [{
        id: 'tasks',
        label: 'Tareas de Scrapeo',
        roles: ['admin']
      }, {
        id: 'integrations',
        label: 'Integraciones',
        roles: ['admin']
      }, {
        id: 'users',
        label: 'Usuarios',
        roles: ['admin']
      }, {
        id: 'roles',
        label: 'Roles y Permisos',
        roles: ['admin']
      }, {
        id: 'audit',
        label: 'Auditoría',
        roles: ['admin']
      }, {
        id: 'settings',
        label: 'Configuración',
        roles: ['admin']
      }, {
        id: 'billing',
        label: 'Plan y Suscripción',
        roles: ['admin']
      }]
    }];
    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };
    navMenu.innerHTML = '';
    MENU.forEach(function (section) {
      var visible = [];
      for (var i = 0; i < section.items.length; i++) {
        if (section.items[i].roles.indexOf(role) !== -1) {
          visible.push(section.items[i]);
        }
      }
      if (visible.length === 0) {
        return;
      }
      var containsActive = false;
      for (var j = 0; j < visible.length; j++) {
        if (visible[j].id === active) {
          containsActive = true;
        }
      }
      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');
      var head = document.createElement('div');
      head.className = 'nav-section-head';
      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);
      head.addEventListener('click', function () {
        if (group.classList.contains('collapsed')) {
          group.classList.remove('collapsed');
        } else {
          group.classList.add('collapsed');
        }
      });
      group.appendChild(head);
      var list = document.createElement('ul');
      list.className = 'nav-group-items';
      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;
        li.addEventListener('click', function () {
          appsmith.triggerEvent('go_' + item.id);
        });
        list.appendChild(li);
      });
      group.appendChild(list);
      navMenu.appendChild(group);
    });
    document.getElementById('viewTitle').textContent = TITLES[active] || 'Dashboard Ejecutivo';
    document.getElementById('logoutBtn').addEventListener('click', function () {
      appsmith.triggerEvent('onLogout');
    });
  } catch (errShell) {
    navMenu.innerHTML = '<li style="color:#A7CDDE;padding:12px;font-size:11px;">ERROR SHELL: ' + errShell.message + '</li>';
    return;
  }
  if ((appsmith.model || {}).active === 'targets') {
    try {
      initTargetsModule();
    } catch (errMod) {
      var area = document.getElementById('contentArea');
      if (area) {
        area.innerHTML = '<div style="color:#2F323B;background:rgba(167,205,222,0.18);border:1px solid rgba(167,205,222,0.65);border-radius:10px;padding:14px;font-size:12px;">ERROR MODULO: ' + errMod.message + '</div>';
      }
    }
  }
  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }
  function fillPlatforms() {
    var sel = document.getElementById('f_platform');
    if (!sel) {
      return;
    }
    var plats = decodeB64(appsmith.model.platformsJson);
    sel.innerHTML = '';
    if (plats.length === 0) {
      ['instagram', 'tiktok', 'facebook', 'x'].forEach(function (c) {
        var op = document.createElement('option');
        op.value = c;
        op.textContent = c;
        sel.appendChild(op);
      });
      return;
    }
    var groups = {};
    plats.forEach(function (p) {
      if (!groups[p.category]) {
        groups[p.category] = [];
      }
      groups[p.category].push(p);
    });
    Object.keys(groups).sort().forEach(function (cat) {
      var og = document.createElement('optgroup');
      og.label = cat;
      groups[cat].forEach(function (p) {
        var op = document.createElement('option');
        op.value = p.code;
        op.textContent = p.display_name;
        og.appendChild(op);
      });
      sel.appendChild(og);
    });
  }
  function renderTable(rows) {
    var wrap = document.getElementById('targetsTable');
    if (!wrap) {
      return;
    }
    if (!rows || rows.length === 0) {
      wrap.innerHTML = '<div class="empty-state">' + '<div class="empty-icon">' + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' + '<circle cx="12" cy="12" r="10"></circle>' + '<circle cx="12" cy="12" r="6"></circle>' + '<circle cx="12" cy="12" r="2"></circle>' + '</svg>' + '</div>' + '<h4>Sin objetivos monitoreados</h4>' + '<p>Registra cuentas y perfiles de redes sociales para comenzar el monitoreo continuo.</p>' + '</div>';
      return;
    }
    var html = '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Plataforma</th>' + '<th>Handle</th>' + '<th>External ID</th>' + '<th>Estado</th>' + '<th>Creado</th>' + '<th class="th-actions">Acciones</th>' + '</tr>' + '</thead>' + '<tbody>';
    rows.forEach(function (r) {
      var badge = r.status === 'active' ? '<span class="badge badge-active">Activo</span>' : '<span class="badge badge-inactive">Inactivo</span>';
      html += '<tr>' + '<td>' + '<span class="plat-name">' + esc(r.platform) + '</span>' + '</td>' + '<td class="cell-strong">' + esc(r.handle) + '</td>' + '<td class="cell-muted">' + esc(r.external_profile_id) + '</td>' + '<td>' + badge + '</td>' + '<td class="cell-muted">' + esc(r.created_fmt) + '</td>' + '<td class="th-actions">' + '<button class="btn-row" data-action="toggle" data-id="' + esc(r.id) + '">' + (r.status === 'active' ? 'Pausar' : 'Activar') + '</button>' + '<button class="btn-row btn-row-danger" data-action="del" data-id="' + esc(r.id) + '">Eliminar</button>' + '</td>' + '</tr>';
    });
    html += '</tbody>' + '</table>';
    wrap.innerHTML = html;
  }
  function renderCatalog(rows) {
    var wrap = document.getElementById('catalogTable');
    if (!wrap) {
      return;
    }
    if (!rows || rows.length === 0) {
      wrap.innerHTML = '<p style="font-size:12px;color:#585A61;">Catálogo no disponible.</p>';
      return;
    }
    var html = '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Plataforma</th>' + '<th>Categoría</th>' + '<th>Estado</th>' + '<th class="th-actions">Acción</th>' + '</tr>' + '</thead>' + '<tbody>';
    rows.forEach(function (p) {
      var badge = p.is_active ? '<span class="badge badge-active">Activa</span>' : '<span class="badge badge-inactive">Inactiva</span>';
      html += '<tr>' + '<td class="cell-strong">' + esc(p.display_name) + '</td>' + '<td class="cell-muted">' + esc(p.category) + '</td>' + '<td>' + badge + '</td>' + '<td class="th-actions">' + '<button class="btn-row" data-action="plat" data-code="' + esc(p.code) + '">' + (p.is_active ? 'Desactivar' : 'Activar') + '</button>' + '</td>' + '</tr>';
    });
    html += '</tbody>' + '</table>';
    wrap.innerHTML = html;
  }
  function initTargetsModule() {
    var area = document.getElementById('contentArea');
    var catalogSection = '';
    if (role === 'admin') {
      catalogSection = '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Catálogo de plataformas</h3>' + '</div>' + '<div id="catalogTable"></div>' + '</section>';
    }
    area.innerHTML = '<section class="form-panel">' + '<div class="panel-head">' + '<h3>Matricular cuenta monitoreada</h3>' + '</div>' + '<form id="targetForm" class="target-form">' + '<div class="field">' + '<label class="field-label" for="f_platform">Plataforma</label>' + '<select id="f_platform" class="sl-input"></select>' + '</div>' + '<div class="field field-grow">' + '<label class="field-label" for="f_handle">Handle</label>' + '<input id="f_handle" class="sl-input" placeholder="@cuenta" required>' + '</div>' + '<div class="field field-grow">' + '<label class="field-label" for="f_external">External Profile ID</label>' + '<input id="f_external" class="sl-input" placeholder="id de la plataforma" required>' + '</div>' + '<button type="submit" class="btn-primary-sm">Registrar cuenta</button>' + '</form>' + '</section>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Cuentas monitoreadas</h3>' + '</div>' + '<div id="targetsTable"></div>' + '</section>' + catalogSection;
    fillPlatforms();
    renderTable(decodeB64(appsmith.model.targetsJson));
    if (role === 'admin') {
      renderCatalog(decodeB64(appsmith.model.catalogJson));
    }
    document.getElementById('targetForm').addEventListener('submit', function (e) {
      e.preventDefault();
      appsmith.updateModel({
        f_platform: document.getElementById('f_platform').value,
        f_handle: document.getElementById('f_handle').value,
        f_external: document.getElementById('f_external').value
      });
      setTimeout(function () {
        appsmith.triggerEvent('onCreateTarget');
      }, 150);
      document.getElementById('f_handle').value = '';
      document.getElementById('f_external').value = '';
    });
    document.getElementById('targetsTable').addEventListener('click', function (e) {
      var btn = e.target.closest('button[data-action]');
      if (!btn) {
        return;
      }
      var id = btn.getAttribute('data-id');
      var act = btn.getAttribute('data-action');
      if (act === 'del') {
        appsmith.updateModel({
          del_id: id
        });
        setTimeout(function () {
          appsmith.triggerEvent('onDeleteTarget');
        }, 150);
      }
      if (act === 'toggle') {
        appsmith.updateModel({
          toggle_id: id
        });
        setTimeout(function () {
          appsmith.triggerEvent('onToggleTarget');
        }, 150);
      }
    });
    var catalogWrap = document.getElementById('catalogTable');
    if (catalogWrap) {
      catalogWrap.addEventListener('click', function (e) {
        var btn = e.target.closest('button[data-action="plat"]');
        if (!btn) {
          return;
        }
        appsmith.updateModel({
          toggle_platform_code: btn.getAttribute('data-code')
        });
        setTimeout(function () {
          appsmith.triggerEvent('onTogglePlatform');
        }, 150);
      });
    }
    var lastT = appsmith.model.targetsJson || '';
    var lastP = appsmith.model.platformsJson || '';
    var lastC = appsmith.model.catalogJson || '';
    function refreshFromModel() {
      var nowT = appsmith.model.targetsJson || '';
      var nowP = appsmith.model.platformsJson || '';
      var nowC = appsmith.model.catalogJson || '';
      if (nowT !== lastT) {
        lastT = nowT;
        renderTable(decodeB64(nowT));
      }
      if (nowP !== lastP) {
        lastP = nowP;
        fillPlatforms();
      }
